contract KaspaFomoRound(
    byte[32] initialLastBuyer,
    int initialEndTimeMs,
    int ticketPriceSompi,
    int extensionMs,
    int maxFutureMs,
    int potCapSompi,
    int minSettlePotSompi,
    int maxSettlementFeeSompi,
    pubkey marketingRecipient,
    pubkey platformRecipient,
    pubkey roundSigner
) {
    int constant BPS = 10000;
    int constant WINNER_BPS = 5000;
    int constant MARKETING_BPS = 3000;
    int constant PLATFORM_BPS = 200;
    int constant RANDOM_SLOT_BPS = 300;
    int constant RANDOM_SLOT_COUNT = 6;

    byte[32] lastBuyer = initialLastBuyer;
    int endTimeMs = initialEndTimeMs;
    int ticketCount = 0;

    function requirePolicy() {
        require(ticketPriceSompi > 0);
        require(extensionMs > 0);
        require(maxFutureMs > 0);
        require(potCapSompi >= ticketPriceSompi);
        require(minSettlePotSompi > 0);
        require(maxSettlementFeeSompi >= 0);
    }

    function requireP2PK(int outputIndex, pubkey recipient, int amountSompi) {
        require(outputIndex >= 0);
        require(amountSompi > 0);
        require(tx.outputs[outputIndex].value == amountSompi);
        require(tx.outputs[outputIndex].scriptPubKey == byte[](new ScriptPubKeyP2PK(recipient)));
    }

    entry buy(sig buyerSig, sig roundSig, byte[32] buyer, int proposedEndTimeMs, int roundOutputIndex) {
        requirePolicy();
        require(checkSig(buyerSig, pubkey(buyer)));
        require(checkSig(roundSig, roundSigner));
        require(OpAuthOutputCount(this.activeInputIndex) == 1);
        require(OpAuthOutputIdx(this.activeInputIndex, 0) == roundOutputIndex);

        require(proposedEndTimeMs > endTimeMs);
        require(proposedEndTimeMs <= endTimeMs + extensionMs);
        require(tx.time >= temporal(proposedEndTimeMs - maxFutureMs));

        int newPotSompi = tx.inputs[this.activeInputIndex].value + ticketPriceSompi;
        require(newPotSompi <= potCapSompi);
        require(tx.outputs[roundOutputIndex].value == newPotSompi);

        validateOutputState(roundOutputIndex, State {
            lastBuyer: buyer,
            endTimeMs: proposedEndTimeMs,
            ticketCount: ticketCount + 1
        });
    }

    entry settle(
        sig selectionSig,
        int settlementFeeSompi,
        pubkey randomRecipient0,
        pubkey randomRecipient1,
        pubkey randomRecipient2,
        pubkey randomRecipient3,
        pubkey randomRecipient4,
        pubkey randomRecipient5
    ) {
        requirePolicy();
        require(checkSig(selectionSig, roundSigner));
        require(tx.time >= temporal(endTimeMs));
        require(OpAuthOutputCount(this.activeInputIndex) == 0);
        require(settlementFeeSompi >= 0);
        require(settlementFeeSompi <= maxSettlementFeeSompi);

        int potSompi = tx.inputs[this.activeInputIndex].value;
        require(potSompi >= minSettlePotSompi);
        int netPotSompi = potSompi - settlementFeeSompi;
        require(netPotSompi > 0);

        int winnerAmountSompi = netPotSompi * WINNER_BPS / BPS;
        int platformAmountSompi = netPotSompi * PLATFORM_BPS / BPS;
        int randomSlotAmountSompi = netPotSompi * RANDOM_SLOT_BPS / BPS;
        require(randomSlotAmountSompi > 0);
        int randomTotalSompi = randomSlotAmountSompi * RANDOM_SLOT_COUNT;
        int marketingAmountSompi = netPotSompi - winnerAmountSompi - platformAmountSompi - randomTotalSompi;
        require(marketingAmountSompi >= netPotSompi * MARKETING_BPS / BPS);

        requireP2PK(0, pubkey(lastBuyer), winnerAmountSompi);
        requireP2PK(1, marketingRecipient, marketingAmountSompi);
        requireP2PK(2, platformRecipient, platformAmountSompi);

        requireP2PK(3, randomRecipient0, randomSlotAmountSompi);
        requireP2PK(4, randomRecipient1, randomSlotAmountSompi);
        requireP2PK(5, randomRecipient2, randomSlotAmountSompi);
        requireP2PK(6, randomRecipient3, randomSlotAmountSompi);
        requireP2PK(7, randomRecipient4, randomSlotAmountSompi);
        requireP2PK(8, randomRecipient5, randomSlotAmountSompi);
    }
